PRAGMA foreign_keys=ON;
CREATE TABLE members(email TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','approver','editor','viewer')), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE templates(id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, version INTEGER NOT NULL, body TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0, approved_by TEXT, source TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE contracts(id TEXT PRIMARY KEY, kind TEXT NOT NULL, title TEXT NOT NULL, party_name TEXT NOT NULL, party_email TEXT NOT NULL, payload TEXT NOT NULL, template_id TEXT NOT NULL REFERENCES templates(id), body TEXT NOT NULL, content_hash TEXT NOT NULL, pdf_key TEXT, pdf_hash TEXT, status TEXT NOT NULL CHECK(status IN ('draft','review','approved','sent','signed','declined','voided','expired')), version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, approved_by TEXT, assigned_to TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, expires_at TEXT, signed_at TEXT, signature_name TEXT, audit_head TEXT NOT NULL DEFAULT 'GENESIS');
CREATE INDEX contracts_status ON contracts(status,updated_at);
CREATE TABLE events(id TEXT PRIMARY KEY, contract_id TEXT NOT NULL REFERENCES contracts(id), version INTEGER NOT NULL, action TEXT NOT NULL, actor TEXT NOT NULL, at TEXT NOT NULL, detail TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL, UNIQUE(contract_id,version));
CREATE TRIGGER immutable_events_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'events immutable'); END;
CREATE TRIGGER immutable_events_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'events immutable'); END;
CREATE TRIGGER immutable_contract BEFORE UPDATE ON contracts WHEN OLD.status IN ('sent','signed','declined','voided','expired') AND (NEW.payload!=OLD.payload OR NEW.body!=OLD.body OR NEW.content_hash!=OLD.content_hash OR NEW.party_email!=OLD.party_email OR NEW.template_id!=OLD.template_id OR NEW.pdf_hash IS NOT OLD.pdf_hash OR NEW.pdf_key IS NOT OLD.pdf_key) BEGIN SELECT RAISE(ABORT,'document immutable'); END;
CREATE TABLE invitations(id TEXT PRIMARY KEY, contract_id TEXT NOT NULL REFERENCES contracts(id), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, contract_id TEXT REFERENCES contracts(id), email TEXT NOT NULL, scope TEXT NOT NULL, expires_at TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, consent_at TEXT, downloaded_at TEXT);
CREATE TABLE challenges(id TEXT PRIMARY KEY, session_hash TEXT NOT NULL, code_hash TEXT NOT NULL, expires_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, consumed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE outbox(id TEXT PRIMARY KEY, contract_id TEXT REFERENCES contracts(id), recipient TEXT NOT NULL, subject TEXT NOT NULL, encrypted_body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, lease_until TEXT, created_at TEXT NOT NULL, sent_at TEXT, error TEXT);
CREATE TABLE comments(id TEXT PRIMARY KEY, contract_id TEXT NOT NULL REFERENCES contracts(id), author TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, resets_at INTEGER NOT NULL);
CREATE TABLE security_events(id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, at TEXT NOT NULL);
